       const tmplKeyForIndex = (i) => (i === 0 ? "main" : tabs[i].name);
       function ensureOpen(key) { if (!openEditors.includes(key)) openEditors.push(key); }

+      // Auto-open every example file that carries content — "open all the files,
+      // but only if not empty". `main` + `data` always open (the entry template
+      // and the root @root context). Each partial, the transform, the helpers
+      // source, and each data overlay open ONLY when non-empty, so an example's
+      // blank scaffold files (e.g. an empty transform) stay closed and the tab
+      // strips reflect only real content. Order: partials before transform/helpers
+      // in the top strip; overlays after data in the bottom strip. Mirrors the
+      // tutorial Open-in-Lab card, which likewise shows a pane only when filled.
+      function autoOpenEditors() {
+        const has = (s) => typeof s === "string" && s.trim() !== "";
+        const open = ["main", "data"];
+        tabs.forEach((t, i) => { if (i > 0 && has(t.source)) open.push(t.name); });
+        if (has(transformSrc)) open.push("transform");
+        if (has(helpersSrc)) open.push("helpers");
+        for (const o of dataOverlays) if (has(o.source)) open.push(o.name);
+        return open;
+      }
+
